import{_ as o,o as r,c as i,a3 as t}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"Audio Recording & Speech-to-Text","description":"Record voice notes, conference meetings with dual-stream audio loopback, and generate AI transcripts with local Whisper.","frontmatter":{"title":"Audio Recording & Speech-to-Text","description":"Record voice notes, conference meetings with dual-stream audio loopback, and generate AI transcripts with local Whisper.","keywords":"audio recording, voice notes, meeting recorder, speech to text, whisper, transcription, transcript drawer","category":"Workspace"},"headers":[],"relativePath":"workspace/audio-recording.md","filePath":"workspace/audio-recording.md","lastUpdated":1791044111000}'),n={name:"workspace/audio-recording.md"};function a(s,e,d,c,l,g){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="audio-recording-speech-to-text" tabindex="-1">Audio Recording &amp; Speech-to-Text <a class="header-anchor" href="#audio-recording-speech-to-text" aria-label="Permalink to &quot;Audio Recording &amp; Speech-to-Text&quot;">​</a></h1><p>Notely includes a dual-stream audio recording engine and speech-to-text pipeline for voice notes and conference call transcriptions.</p><hr><h2 id="_1-recording-modes" tabindex="-1">1. Recording Modes <a class="header-anchor" href="#_1-recording-modes" aria-label="Permalink to &quot;1. Recording Modes&quot;">​</a></h2><p>Trigger audio recording via <code>Alt + V</code>, the <strong>🎙️ Record Audio</strong> toolbar button in the Markdown editor, or the <strong>Quick Capture Bar</strong> on the landing dashboard.</p><ol><li><strong>Meeting Mode (Mic + System Loopback)</strong>: <ul><li>Captures microphone input and Windows system audio (Zoom, Google Meet, Microsoft Teams, YouTube) concurrently.</li><li>Merges both streams into a synchronized stereo track via Web Audio API.</li></ul></li><li><strong>Microphone Only</strong>: <ul><li>Voice memo and dictation capture from your primary recording device.</li></ul></li><li><strong>System Audio Only</strong>: <ul><li>Records desktop/speaker audio output without microphone commentary.</li></ul></li></ol><hr><h2 id="_2-speech-to-text-stt-engines" tabindex="-1">2. Speech-to-Text (STT) Engines <a class="header-anchor" href="#_2-speech-to-text-stt-engines" aria-label="Permalink to &quot;2. Speech-to-Text (STT) Engines&quot;">​</a></h2><p>Configure STT preferences in <strong>AI -&gt; AI Settings -&gt; Speech-to-Text</strong>:</p><ul><li><strong>Local ONNX Whisper (Offline)</strong>: <ul><li>Runs on-device via WebAssembly/ONNX Runtime.</li><li>Models: <code>whisper-tiny.en</code> (~40MB), <code>whisper-base.en</code> (~140MB), <code>whisper-small</code> (~460MB).</li><li>Private, zero external network traffic.</li></ul></li><li><strong>Cloud Whisper</strong>: <ul><li>High-throughput cloud transcription via <strong>Groq</strong> (<code>whisper-large-v3</code>) or <strong>OpenAI</strong> (<code>whisper-1</code>).</li><li>Sub-second turnaround using your configured API keys.</li></ul></li></ul><hr><h2 id="_3-storage-markdown-integration" tabindex="-1">3. Storage &amp; Markdown Integration <a class="header-anchor" href="#_3-storage-markdown-integration" aria-label="Permalink to &quot;3. Storage &amp; Markdown Integration&quot;">​</a></h2><ul><li><strong>Asset Bundles</strong>: Audio and video recordings are stored inside isolated bundle directories: <ul><li>Audio: <code>{workspace}/media/audio/&lt;recording_id&gt;/&lt;recording_id&gt;.webm</code></li><li>Companion Transcripts: <code>{workspace}/media/audio/&lt;recording_id&gt;/transcript.json</code></li></ul></li><li><strong>Editor Markdown Preview</strong>: <ul><li>Audio files render interactive player cards with waveform visualizers.</li><li>Companion transcripts render rich <code>.markdown-transcript-card</code> elements with View, Copy Text/Markdown, and Download actions.</li></ul></li><li><strong>Synchronized Transcript Drawer</strong>: Clicking any audio or video recording with companion transcript data opens the media player alongside an interactive, timestamp-synchronized side drawer.</li></ul><hr><h2 id="_4-diagrams-media-asset-manager-integration" tabindex="-1">4. Diagrams &amp; Media Asset Manager Integration <a class="header-anchor" href="#_4-diagrams-media-asset-manager-integration" aria-label="Permalink to &quot;4. Diagrams &amp; Media Asset Manager Integration&quot;">​</a></h2><ul><li>Filter by <strong>Audio</strong>, <strong>Videos</strong>, and <strong>Transcripts</strong> categories in <code>Workspace -&gt; Diagrams &amp; Media</code> (<code>Ctrl/Cmd + Alt + M</code>).</li><li><strong>On-Demand AI Transcript Generation (<code>✨</code>)</strong>: Run speech-to-text on any existing recording without re-recording.</li><li><strong>Reference Tracking</strong>: View exactly which notes and lines reference the audio/video recordings and transcripts.</li></ul>',16)])])}const h=o(n,[["render",a]]);export{u as __pageData,h as default};
